/**
 * Utility to inject or patch duration metadata in WebM files generated by MediaRecorder.
 * In Chromium browsers, MediaRecorder produces WebM files with duration = Infinity/0
 * because the duration is unknown when the recording starts.
 * This tool parses the EBML Segment and Info header and injects the Duration element.
 */

export async function fixWebmDuration(blob: Blob, durationMs: number): Promise<Blob> {
  if (!durationMs || isNaN(durationMs) || durationMs <= 0) {
    return blob;
  }

  try {
    const buffer = await blob.arrayBuffer();
    const view = new DataView(buffer);
    const bytes = new Uint8Array(buffer);

    // Look for EBML Header: 1A 45 DF A3
    if (bytes[0] !== 0x1A || bytes[1] !== 0x45 || bytes[2] !== 0xDF || bytes[3] !== 0xA3) {
      return blob; // Not standard EBML
    }

    // Search for Segment element: 18 53 80 67
    let segmentOffset = -1;
    for (let i = 0; i < Math.min(bytes.length - 4, 1024); i++) {
      if (bytes[i] === 0x18 && bytes[i + 1] === 0x53 && bytes[i + 2] === 0x80 && bytes[i + 3] === 0x67) {
        segmentOffset = i;
        break;
      }
    }

    if (segmentOffset === -1) return blob;

    // Search for Segment Info element: 15 49 A9 66
    let infoOffset = -1;
    for (let i = segmentOffset; i < Math.min(bytes.length - 4, segmentOffset + 2048); i++) {
      if (bytes[i] === 0x15 && bytes[i + 1] === 0x49 && bytes[i + 2] === 0xA9 && bytes[i + 3] === 0x66) {
        infoOffset = i;
        break;
      }
    }

    if (infoOffset === -1) return blob;

    // Check if Duration element (44 89) already exists in Info
    let durationOffset = -1;
    for (let i = infoOffset; i < Math.min(bytes.length - 6, infoOffset + 512); i++) {
      if (bytes[i] === 0x44 && bytes[i + 1] === 0x89) {
        durationOffset = i;
        break;
      }
    }

    if (durationOffset !== -1) {
      // Overwrite existing duration
      const lenByte = bytes[durationOffset + 2];
      const dataLen = lenByte & 0x0F;
      if (dataLen === 4) {
        view.setFloat32(durationOffset + 3, durationMs, false); // Big endian float32
        return new Blob([buffer], { type: blob.type || 'video/webm' });
      } else if (dataLen === 8) {
        view.setFloat64(durationOffset + 3, durationMs, false); // Big endian float64
        return new Blob([buffer], { type: blob.type || 'video/webm' });
      }
    }

    // Duration element wasn't present; construct a Duration element:
    // ID: 0x44 0x89 (Duration)
    // Length: 0x84 (4 bytes float32)
    // Value: durationMs as float32
    const durationElem = new Uint8Array(7);
    durationElem[0] = 0x44;
    durationElem[1] = 0x89;
    durationElem[2] = 0x84; // 4 bytes
    const durView = new DataView(durationElem.buffer);
    durView.setFloat32(3, durationMs, false);

    // Insert durationElem right after Info header (Info ID + length descriptor)
    // Find length of Info length descriptor:
    let infoHeaderLen = 4; // Info ID is 4 bytes
    const firstInfoLenByte = bytes[infoOffset + 4];
    let infoLenBytes = 1;
    if ((firstInfoLenByte & 0x80) === 0x80) infoLenBytes = 1;
    else if ((firstInfoLenByte & 0x40) === 0x40) infoLenBytes = 2;
    else if ((firstInfoLenByte & 0x20) === 0x20) infoLenBytes = 3;
    else if ((firstInfoLenByte & 0x10) === 0x10) infoLenBytes = 4;
    infoHeaderLen += infoLenBytes;

    const insertPos = infoOffset + infoHeaderLen;
    const newBytes = new Uint8Array(bytes.length + durationElem.length);
    newBytes.set(bytes.subarray(0, insertPos), 0);
    newBytes.set(durationElem, insertPos);
    newBytes.set(bytes.subarray(insertPos), insertPos + durationElem.length);

    return new Blob([newBytes.buffer], { type: blob.type || 'video/webm' });
  } catch (err) {
    console.warn('fixWebmDuration fallback to original blob:', err);
    return blob;
  }
}
